import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.io.IOException;

public class Solution implements Runnable {
    private final BufferedReader inf;
    private final PrintWriter ouf;

    public Solution() {
        this(new BufferedReader(new InputStreamReader(System.in)), new PrintWriter(System.out));
    }

    public Solution(BufferedReader inf, PrintWriter ouf) {
        this.inf = inf;
        this.ouf = ouf;
    }

    private void solve() {
        try {
            String s = inf.readLine();
            String[] cards = inf.readLine().split(" ");
            boolean found = false;
            for (String card : cards) {
                if (s.charAt(0) == card.charAt(0) || s.charAt(1) == card.charAt(1)) {
                    found = true;
                    break;
                }
            }
            ouf.println(found ? "YES" : "NO");
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    @Override
    public void run() {
        solve();
        ouf.close();
    }

    public static void main(String[] args) {
        new Thread(null, new Solution(), "name", 1 << 27).start();
    }
}

